// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    function testFuzz_property(address from, uint256 tosLenSeed) public {
        uint256 len = bound(tosLenSeed, 1, 10);

        CounterCallee helper = new CounterCallee();

        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, i, tosLenSeed)))));
        }

        bool ok;
        try c.transfer(from, address(helper), tos, 42) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(helper.callCount() == len);
        } else {
            assertTrue(helper.callCount() == 0);
        }
    }
}

contract CounterCallee {
    uint256 public callCount = 0;
    fallback() external payable {
        callCount += 1;
    }
    receive() external payable {
        callCount += 1;
    }
}
